import type { DesignProfiles } from './DesignProfiles';
import type { MemoryRuntime } from './MemoryRuntime';
import * as memoryComponents from './memoryComponents';
import { DesignReferenceSearchRequestSchema } from '../../types/design-library';

const MATCH_SIMILARITY = 0.9;

interface StoredMemory {
  id: string;
  content: string;
  metadata: { referenceId: string; revision: number; writeId: string };
}

export const memoryEngine = () => {
  const memories: StoredMemory[] = [];
  let written = 0;
  const request = async (
    _runtime: unknown,
    endpoint: string,
    body: Record<string, unknown>,
    method = 'POST',
  ): Promise<unknown> => {
    if (endpoint === '/v4/memories/list')
      return {
        memoryEntries: memories,
        pagination: { currentPage: 1, totalPages: 1 },
      };
    if (endpoint === '/v4/memories' && method === 'DELETE') {
      memories.splice(
        memories.findIndex((memory) => memory.id === body.id),
        1,
      );
      return {};
    }
    if (endpoint === '/v4/memories') {
      const [memory] = body.memories as Omit<StoredMemory, 'id'>[];
      written += 1;
      const stored = { ...memory, id: `memory-${written}` };
      memories.push(stored);
      return { memories: [{ id: stored.id }] };
    }
    if (endpoint === '/v4/search') {
      const words = String(body.q).toLowerCase().split(/\s+/);
      return {
        results: memories
          .filter((memory) =>
            words.some((word) => memory.content.toLowerCase().includes(word)),
          )
          .map((memory) => ({ ...memory, similarity: MATCH_SIMILARITY })),
      };
    }
    throw new Error(`Unexpected engine request ${endpoint}`);
  };
  return {
    memories,
    request,
    engine: { request } as unknown as MemoryRuntime,
  };
};

export const searchWithoutEngine = (
  profiles: DesignProfiles,
  query: string,
) => {
  jest
    .spyOn(memoryComponents, 'isMemoryPlatformSupported')
    .mockReturnValue(false);
  return profiles.search(DesignReferenceSearchRequestSchema.parse({ query }));
};
